def solve_small_v2(n):
    black_squares = []
    for r in range(n):
        for c in range(n):
            if (r + c) % 2 == 0:
                black_squares.append((r, c))

    B = len(black_squares)

    # We need to find minimum k such that there exist k non-overlapping trominos 
    # that cover all black squares.

    all_trominos = []
    for r in range(n):
        for c in range(n):
            orientations = [
                [(r, c), (r+1, c), (r, c+1)],
                [(r, c), (r-1, c), (r, c+1)],
                [(r, c), (r+1, c), (r, c-1)],
                [(r, c), (r-1, c), (r, c-1)]
            ]
            for tromino in orientations:
                if all(0 <= row < n and 0 <= col < n for row, col in tromino):
                    all_trominos.append(set(tromino))

    # Filter trominos that cover 1 or 2 black squares
    valid_trominos = []
    for t in all_trominos:
        count = 0
        for sq in t:
            if (sq[0] + sq[1]) % 2 == 0:
                count += 1
        if count == 1 or count == 2:
            valid_trominos.append(t)

    def backtrack(remaining_black, used_squares, k_left):
        if not remaining_black:
            return True
        if k_left <= 0:
            return False

        # To optimize, pick the black square with the fewest valid trominos
        best_b = None
        best_trominos = []
        min_options = float('inf')

        for b in remaining_black:
            options = [t for t in valid_trominos if b in t and t.isdisjoint(used_squares)]
            if len(options) < min_options:
                min_options = len(options)
                best_b = b
                best_trominos = options
            if min_options == 0: break

        if min_options == 0:
            return False

        for t in best_trominos:
            if backtrack(remaining_black - (t & remaining_black), used_squares | t, k_left - 1):
                return True
        return False

    for k in range((B + 1) // 2, len(valid_trominos) + 1):
        if backtrack(set(black_squares), set(), k):
            return k
    return None

